CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED');
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL, url TEXT, published_at TEXT, verified_at TEXT NOT NULL, limitations TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS drivers(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','driver')), driver_id TEXT REFERENCES drivers(id), operations TEXT NOT NULL CHECK(json_valid(operations)), enabled INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, CHECK(role='admin' OR driver_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS user_scopes(user_id TEXT NOT NULL REFERENCES users(id), owner_id TEXT NOT NULL REFERENCES organizations(id), PRIMARY KEY(user_id,owner_id));
CREATE TABLE IF NOT EXISTS auth_sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS vehicles(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), driver_id TEXT REFERENCES drivers(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, capacity_kwh REAL NOT NULL CHECK(capacity_kwh>0), payload_kg INTEGER NOT NULL CHECK(payload_kg>0), soc REAL CHECK(soc BETWEEN 0 AND 100), source TEXT NOT NULL DEFAULT 'SIMULATED', source_id TEXT REFERENCES sources(id), data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS stations(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, mode TEXT NOT NULL, power_kw REAL NOT NULL CHECK(power_kw>=0), longitude REAL NOT NULL, latitude REAL NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), station_id TEXT NOT NULL REFERENCES stations(id), status TEXT NOT NULL, connection TEXT NOT NULL, power_kw REAL NOT NULL CHECK(power_kw>=0), version INTEGER NOT NULL DEFAULT 1, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS demands(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, quantity_kg INTEGER NOT NULL CHECK(quantity_kg>0), allocated_kg INTEGER NOT NULL DEFAULT 0 CHECK(allocated_kg>=0 AND allocated_kg<=quantity_kg), created_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), demand_id TEXT NOT NULL REFERENCES demands(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, quantity_kg INTEGER NOT NULL CHECK(quantity_kg>0), cancelled_kg INTEGER NOT NULL DEFAULT 0 CHECK(cancelled_kg>=0 AND cancelled_kg<=quantity_kg), start_at TEXT NOT NULL, finish_at TEXT NOT NULL, created_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL CHECK(json_valid(data)), CHECK(finish_at>start_at));
CREATE TABLE IF NOT EXISTS simulations(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), order_id TEXT NOT NULL REFERENCES orders(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, order_version INTEGER NOT NULL, created_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'DERIVED_SIMULATION', data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), order_id TEXT NOT NULL REFERENCES orders(id), vehicle_id TEXT NOT NULL REFERENCES vehicles(id), driver_id TEXT NOT NULL REFERENCES drivers(id), simulation_id TEXT REFERENCES simulations(id), status TEXT NOT NULL, notification TEXT NOT NULL DEFAULT '未投递', version INTEGER NOT NULL DEFAULT 1, quantity_kg INTEGER NOT NULL CHECK(quantity_kg>0), reported_kg INTEGER NOT NULL DEFAULT 0 CHECK(reported_kg>=0), verified_kg INTEGER NOT NULL DEFAULT 0 CHECK(verified_kg>=0), start_at TEXT NOT NULL, finish_at TEXT NOT NULL, created_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)), CHECK(finish_at>start_at));
CREATE TABLE IF NOT EXISTS trips(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, task_id TEXT NOT NULL REFERENCES tasks(id), owner_id TEXT NOT NULL REFERENCES organizations(id), status TEXT NOT NULL, loaded_kg INTEGER NOT NULL DEFAULT 0, delivered_kg INTEGER NOT NULL DEFAULT 0, verified_kg INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, occurred_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'MANUAL_SIMULATION', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, source_key TEXT NOT NULL, event_key TEXT NOT NULL, task_id TEXT REFERENCES tasks(id), trip_id TEXT REFERENCES trips(id), kind TEXT NOT NULL, occurred_at TEXT NOT NULL, received_at TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(source_key,event_key));
CREATE TABLE IF NOT EXISTS charging(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), task_id TEXT REFERENCES tasks(id), vehicle_id TEXT NOT NULL REFERENCES vehicles(id), station_id TEXT NOT NULL REFERENCES stations(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, arrival_at TEXT NOT NULL, quantity_kwh REAL NOT NULL CHECK(quantity_kwh>0), source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), station_id TEXT NOT NULL REFERENCES stations(id), vehicle_id TEXT NOT NULL REFERENCES vehicles(id), plan_id TEXT REFERENCES charging(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, quantity_kwh REAL NOT NULL CHECK(quantity_kwh>=0), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), start_at TEXT NOT NULL, finish_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS costs(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), task_id TEXT REFERENCES tasks(id), session_id TEXT REFERENCES sessions(id), replacement_id TEXT REFERENCES costs(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, nature TEXT NOT NULL CHECK(nature IN ('预计','实际')), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), created_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), task_id TEXT REFERENCES tasks(id), vehicle_id TEXT REFERENCES vehicles(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, severity TEXT NOT NULL, created_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY, resource TEXT NOT NULL, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES organizations(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'SIMULATED', data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), owner_id TEXT REFERENCES organizations(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, before_version INTEGER, after_version INTEGER, created_at TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS command_results(user_id TEXT NOT NULL REFERENCES users(id), command_key TEXT NOT NULL, request_hash TEXT NOT NULL, response TEXT NOT NULL CHECK(json_valid(response)), created_at TEXT NOT NULL, PRIMARY KEY(user_id,command_key));
CREATE INDEX IF NOT EXISTS idx_orders_owner_state ON orders(owner_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tasks_driver_state ON tasks(driver_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tasks_vehicle_window ON tasks(vehicle_id,start_at,finish_at);
CREATE INDEX IF NOT EXISTS idx_tasks_order ON tasks(order_id,status);
CREATE INDEX IF NOT EXISTS idx_trips_task ON trips(task_id,status);
CREATE INDEX IF NOT EXISTS idx_records_resource_owner ON records(resource,owner_id,status);
CREATE INDEX IF NOT EXISTS idx_costs_scope ON costs(owner_id,nature,status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_charging_station_time ON charging(station_id,arrival_at,status);
CREATE INDEX IF NOT EXISTS idx_audit_owner_time ON audit(owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS telemetry(id TEXT PRIMARY KEY,vehicle_id TEXT NOT NULL REFERENCES vehicles(id),owner_id TEXT NOT NULL REFERENCES organizations(id),occurred_at TEXT NOT NULL,longitude REAL NOT NULL,latitude REAL NOT NULL,soc REAL NOT NULL CHECK(soc BETWEEN 0 AND 100),speed_kmh REAL NOT NULL CHECK(speed_kmh>=0),source TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_telemetry_vehicle_time ON telemetry(vehicle_id,occurred_at);
CREATE TABLE IF NOT EXISTS agent_conversations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),owner_id TEXT NOT NULL REFERENCES organizations(id),capability TEXT NOT NULL CHECK(capability IN('AUTO','DEMAND','SIMULATION','DISPATCH','CHARGING','INCIDENT','PLANNING')),title TEXT NOT NULL,context_resource TEXT,context_id TEXT,draft TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(draft)),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_turns(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES agent_conversations(id),request_key TEXT NOT NULL,question TEXT NOT NULL,response TEXT NOT NULL CHECK(json_valid(response)),created_at TEXT NOT NULL,UNIQUE(conversation_id,request_key));
CREATE INDEX IF NOT EXISTS idx_agent_conversations_account ON agent_conversations(user_id,owner_id,archived,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_turns_conversation ON agent_turns(conversation_id,created_at,id);
